package vn.hust.restaurant.view;
import java.awt.*;import java.math.*;import java.util.*;import javax.swing.*;import javax.swing.table.*;import vn.hust.restaurant.config.AppContext;import vn.hust.restaurant.model.MenuItem;
public class MenuPanel extends JPanel implements Refreshable{private final AppContext ctx;private final JTextField search=new JTextField(20);private final DefaultTableModel model=Ui.model("ID","Mã","Danh mục","Tên món","ĐVT","Đơn giá","Trạng thái");private final JTable table=new JTable(model);private java.util.List<vn.hust.restaurant.model.MenuItem>data=java.util.List.of();public MenuPanel(AppContext c){ctx=c;setLayout(new BorderLayout());JButton add=new JButton("Thêm"),edit=new JButton("Sửa"),toggle=new JButton("Còn/Hết món"),reload=new JButton("Làm mới");add(Ui.toolbar(new JLabel("Tìm:"),search,reload,add,edit,toggle),BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);reload.addActionListener(e->refresh());search.addActionListener(e->refresh());add.addActionListener(e->edit(null));edit.addActionListener(e->{int r=table.getSelectedRow();if(r>=0)edit(data.get(r));});toggle.addActionListener(e->{int r=table.getSelectedRow();if(r>=0)Ui.run(this,()->{vn.hust.restaurant.model.MenuItem x=data.get(r);ctx.menu.toggle(x.id(),!x.available());refresh();});});refresh();}
 public void refresh(){Ui.run(this,()->{data=ctx.menu.list(search.getText(),false);model.setRowCount(0);for(vn.hust.restaurant.model.MenuItem x:data)model.addRow(new Object[]{x.id(),x.code(),x.categoryName(),x.name(),x.unit(),x.price(),x.available()?"CÒN MÓN":"HẾT MÓN"});});}
 private void edit(vn.hust.restaurant.model.MenuItem x){Ui.run(this,()->{Map<Integer,String>cats=ctx.menu.categories();JComboBox<String>cat=new JComboBox<>(cats.values().toArray(String[]::new));JTextField code=Ui.field(x==null?"MON"+(System.currentTimeMillis()%100000):x.code(),15),name=Ui.field(x==null?"":x.name(),20),unit=Ui.field(x==null?"phần":x.unit(),10),price=Ui.field(x==null?"0":x.price().toPlainString(),12),desc=Ui.field(x==null?"":x.description(),20);if(x!=null){int i=new ArrayList<>(cats.keySet()).indexOf(x.categoryId());cat.setSelectedIndex(Math.max(0,i));}Object[]form={"Mã món",code,"Danh mục",cat,"Tên món",name,"Đơn vị",unit,"Đơn giá",price,"Mô tả",desc};if(JOptionPane.showConfirmDialog(this,form,x==null?"Thêm món":"Sửa món",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION){int catId=new ArrayList<>(cats.keySet()).get(cat.getSelectedIndex());ctx.menu.save(new vn.hust.restaurant.model.MenuItem(x==null?0:x.id(),code.getText(),catId,String.valueOf(cat.getSelectedItem()),name.getText(),unit.getText(),Ui.dec(price.getText()),desc.getText(),x==null||x.available()));refresh();}});}}
